create or replace function public.walker_confirm_handover_completed(p_request_id uuid,p_latitude double precision,p_longitude double precision) returns void language plpgsql security definer set search_path='' as $$ declare v_booking uuid; begin if auth.uid() is null then raise exception 'Authentication required'; end if; if p_latitude is null or p_longitude is null or p_latitude not between -90 and 90 or p_longitude not between -180 and 180 then raise exception 'Valid GPS coordinates required'; end if; select h.booking_id into v_booking from public.handover_requests h where h.id=p_request_id and h.walker_id=auth.uid() and h.customer_decision='yes' and h.admin_decision='approved' for update; if not found then raise exception 'Both customer YES and Admin approval are required before completion'; end if; if exists(select 1 from public.walk_events where booking_id=v_booking and event_type='handover_completed' and note like '%'||p_request_id::text||'%') then raise exception 'Handover already marked complete'; end if; insert into public.walker_locations(walker_id,booking_id,latitude,longitude) values(auth.uid(),v_booking,p_latitude,p_longitude); insert into public.walk_events(booking_id,actor_id,event_type,note) values(v_booking,auth.uid(),'handover_completed','Approved outside handover completed; request '||p_request_id::text||'; GPS recorded'); end $$;
revoke all on function public.walker_confirm_handover_completed(uuid,double precision,double precision) from public,anon;
grant execute on function public.walker_confirm_handover_completed(uuid,double precision,double precision) to authenticated;